            VStack(alignment: .leading, spacing: 10) {
                Text("Apple").accessibilityRotorEntry(id: "apple", in: fruit).probe("apple")
                Text("Banana").accessibilityRotorEntry(id: "banana", in: fruit).probe("banana")
