}

struct KeyboardItem: Identifiable, Hashable {
    let id: Int
    let name: String
}

struct KeyboardSheet: View {
    @Environment(\.dismiss) private var dismiss
    var body: some View {
        VStack(spacing: 12) {
            Text("Sheet content")
            Button("Done") { dismiss() }
        }
    }
}

public enum KeyboardFixtures {
