                NavigationLink(destination: Text("Detail")) { Label("Go", image: "icon") }.probe("labelLink")
                NavigationLink("Value", value: 1).probe("valueLink")
                NavigationLink("Wide") { Text("Detail") }.frame(maxWidth: .infinity).probe("wideLink")
            }
