// Representable fixtures (`ios/representable/…`, decision 0014 Phase 2): SwiftUI views hosting
// UIKit views and view controllers, rendered by Apple's SwiftUI over Apple's UIKit on the iPhone
// simulator and reproduced by SwiftUIWebUIKit over UIKitWeb. They pin how SwiftUI sizes a
// representable from the UIKit view's intrinsic content size and priorities, how the
// representable's own `sizeThatFits` is honoured, how it spaces and aligns next to SwiftUI
// views, and that updates flow through `updateUIView`.
import SwiftUI
import FixtureKit
#if canImport(UIKit)
import UIKit

/// A plain table whose three rows are `UIHostingConfiguration`s.
struct HostingCellsTable: UIViewRepresentable {
    final class Source: NSObject, UITableViewDataSource {
        func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int { 3 }
        func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
            let cell = UITableViewCell(style: .default, reuseIdentifier: nil)
            switch indexPath.row {
            case 0:
                cell.contentConfiguration = UIHostingConfiguration {
                    HStack {
                        Text("Row 1")
                        Spacer()
                        Text("Detail").foregroundStyle(.secondary)
                    }
                }
            case 1:
                cell.contentConfiguration = UIHostingConfiguration {
                    HStack {
                        Text("Row 2")
                        Spacer()
                        Text("Detail").foregroundStyle(.secondary)
                    }
                }
                .margins(.horizontal, 40)
                .background(Color.yellow)
            default:
                cell.contentConfiguration = UIHostingConfiguration {
                    Text("Row 3")
                }
                .minSize(height: 80)
            }
            return cell
        }
    }

    func makeCoordinator() -> Source { Source() }
    func makeUIView(context: Context) -> UITableView {
        let table = UITableView(frame: .zero, style: .plain)
        table.dataSource = context.coordinator
        table.isScrollEnabled = false
        return table
    }
    func updateUIView(_ uiView: UITableView, context: Context) {}
}

/// A plain table whose rows host colours through `UIHostingConfiguration` with different
/// margins: the row heights show the default vertical margins and the 56 pt floor.
struct HostingMarginsTable: UIViewRepresentable {
    final class Source: NSObject, UITableViewDataSource {
        func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int { 4 }
        func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
            let cell = UITableViewCell(style: .default, reuseIdentifier: nil)
            switch indexPath.row {
            case 0: cell.contentConfiguration = UIHostingConfiguration { Color.green.frame(height: 60) }.background(Color.yellow)
            case 1: cell.contentConfiguration = UIHostingConfiguration { Color.green.frame(height: 60) }.background(Color.yellow).margins(.all, 0)
            case 2: cell.contentConfiguration = UIHostingConfiguration { Color.green.frame(height: 20) }.background(Color.yellow).margins(.all, 0)
            default: cell.contentConfiguration = UIHostingConfiguration { Color.green.frame(height: 20) }.background(Color.yellow).margins(.vertical, 30)
            }
            return cell
        }
    }

    func makeCoordinator() -> Source { Source() }
    func makeUIView(context: Context) -> UITableView {
        let table = UITableView(frame: .zero, style: .plain)
        table.dataSource = context.coordinator
        table.isScrollEnabled = false
        return table
    }
    func updateUIView(_ uiView: UITableView, context: Context) {}
}

/// A collection view in the plain list layout whose self-sizing cells host colours of three
/// heights through `UIHostingConfiguration`.
struct HostingCollection: UIViewRepresentable {
    final class Coordinator {
        var source: UICollectionViewDiffableDataSource<Int, Int>?
    }

    func makeCoordinator() -> Coordinator { Coordinator() }
    func makeUIView(context: Context) -> UICollectionView {
        let layout = UICollectionViewCompositionalLayout.list(using: UICollectionLayoutListConfiguration(appearance: .plain))
        let collection = UICollectionView(frame: .zero, collectionViewLayout: layout)
        collection.isScrollEnabled = false
        let registration = UICollectionView.CellRegistration<UICollectionViewListCell, Int> { cell, _, height in
            cell.contentConfiguration = UIHostingConfiguration { Color.green.frame(height: CGFloat(height)) }.background(Color.yellow)
        }
        let source = UICollectionViewDiffableDataSource<Int, Int>(collectionView: collection) { collection, indexPath, item in
            collection.dequeueConfiguredReusableCell(using: registration, for: indexPath, item: item)
        }
        var snapshot = NSDiffableDataSourceSnapshot<Int, Int>()
        snapshot.appendSections([0])
        snapshot.appendItems([20, 60, 100])
        source.apply(snapshot, animatingDifferences: false)
        context.coordinator.source = source
        return collection
    }
    func updateUIView(_ uiView: UICollectionView, context: Context) {}
}

/// A navigation controller whose screen is a hosting controller: SwiftUI's `navigationTitle`
/// and `toolbar` drive the UIKit bar.
struct HostingNavItemBox: UIViewControllerRepresentable {
    func makeUIViewController(context: Context) -> UIViewController {
        let hosting = UIHostingController(rootView: HostingNavContent())
        return UINavigationController(rootViewController: hosting)
    }
    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {}
}

struct HostingNavContent: View {
    var body: some View {
        VStack { Text("Content") }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
            .navigationTitle("Settings")
            #if canImport(SwiftUIWebCore) || os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) { Button("Save") {} }
            }
    }
}

@Observable final class HostingSizingModel {
    var tall = false
}

/// A vertical stack view holding a hosting controller's view (sized by its intrinsic content
/// size) over a red view: when the hosted content grows, the red view moves down.
struct HostingSizingBox: UIViewRepresentable {
    let model: HostingSizingModel

    final class Coordinator {
        var hosting: UIHostingController<HostingSizingContent>?
    }

    func makeCoordinator() -> Coordinator { Coordinator() }
    func makeUIView(context: Context) -> UIStackView {
        let hosting = UIHostingController(rootView: HostingSizingContent(model: model))
        hosting.sizingOptions = .intrinsicContentSize
        context.coordinator.hosting = hosting
        let red = UIView()
        red.backgroundColor = .systemRed
        red.translatesAutoresizingMaskIntoConstraints = false
        red.heightAnchor.constraint(equalToConstant: 30).isActive = true
        let stack = UIStackView(arrangedSubviews: [hosting.view, red])
        stack.axis = .vertical
        stack.alignment = .fill
        stack.distribution = .fill
        return stack
    }
    func updateUIView(_ uiView: UIStackView, context: Context) {
        _ = model.tall
    }
    /// The stack's fitting height: the hosted content's intrinsic size plus the red view.
    func sizeThatFits(_ proposal: ProposedViewSize, uiView: UIStackView, context: Context) -> CGSize? {
        CGSize(width: proposal.width ?? 200, height: uiView.systemLayoutSizeFitting(UIView.layoutFittingCompressedSize).height)
    }
}

struct HostingSizingContent: View {
    let model: HostingSizingModel
    var body: some View {
        Color.green.frame(height: model.tall ? 80 : 40)
    }
}

/// A 60 × 40 image drawn by an image renderer: a blue field with a green disc.
@MainActor func renderedFixtureImage() -> UIImage {
    UIGraphicsImageRenderer(size: CGSize(width: 60, height: 40)).image { context in
        UIColor.systemBlue.setFill()
        context.fill(CGRect(x: 0, y: 0, width: 60, height: 40))
        UIColor.systemGreen.setFill()
        UIBezierPath(ovalIn: CGRect(x: 10, y: 5, width: 30, height: 30)).fill()
    }
}

/// A view that turns red while the pointer hovers over it (`UIHoverGestureRecognizer`) and
/// asks for a text-beam pointer (`UIPointerInteraction`).
final class HoverView: UIView, UIPointerInteractionDelegate {
    static func make() -> HoverView {
        let view = HoverView()
        view.backgroundColor = .systemBlue
        let hover = UIHoverGestureRecognizer()
        #if canImport(SwiftUIWebCore)
        hover.addTarget { [weak view] recognizer in view?.apply(recognizer.state) }   // UIKitWeb: closure targets, no selectors
        #else
        hover.addTarget(view, action: #selector(hovered(_:)))
        #endif
        view.addGestureRecognizer(hover)
        view.addInteraction(UIPointerInteraction(delegate: view))
        return view
    }

    func apply(_ state: UIGestureRecognizer.State) {
        switch state {
        case .began, .changed: backgroundColor = .systemRed
        default: backgroundColor = .systemBlue
        }
    }

    #if !canImport(SwiftUIWebCore)
    @objc func hovered(_ recognizer: UIHoverGestureRecognizer) { apply(recognizer.state) }
    #endif

    func pointerInteraction(_ interaction: UIPointerInteraction, styleFor region: UIPointerRegion) -> UIPointerStyle? {
        UIPointerStyle(shape: .horizontalBeam(length: 20))
    }
}

/// The hover view over a system button with the pointer effect on.
struct HoverBox: UIViewRepresentable {
    func makeUIView(context: Context) -> UIStackView {
        let button = UIButton(type: .system)
        button.setTitle("Tap", for: .normal)
        button.isPointerInteractionEnabled = true
        let stack = UIStackView(arrangedSubviews: [HoverView.make(), button])
        stack.axis = .vertical
        stack.distribution = .fillEqually
        return stack
    }
    func updateUIView(_ uiView: UIStackView, context: Context) {}
}

@Observable final class HostingStateModel {
    var selected = false
}

/// A table whose rows rebuild their hosted content from the cell's configuration state
/// (`configurationUpdateHandler`): the selected row says so on a yellow ground.
struct HostingStateTable: UIViewRepresentable {
    let model: HostingStateModel

    final class Source: NSObject, UITableViewDataSource {
        func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int { 2 }
        func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
            let cell = UITableViewCell(style: .default, reuseIdentifier: nil)
            let number = indexPath.row + 1
            cell.configurationUpdateHandler = { cell, state in
                cell.contentConfiguration = UIHostingConfiguration {
                    HStack {
                        Text(state.isSelected ? "Selected" : "Row \(number)")
                        Spacer()
                    }
                }
                .background(state.isSelected ? Color.yellow : Color.clear)
            }
            return cell
        }
    }

    func makeCoordinator() -> Source { Source() }
    func makeUIView(context: Context) -> UITableView {
        let table = UITableView(frame: .zero, style: .plain)
        table.dataSource = context.coordinator
        table.isScrollEnabled = false
        return table
    }
    func updateUIView(_ uiView: UITableView, context: Context) {
        if model.selected {
            uiView.selectRow(at: IndexPath(row: 0, section: 0), animated: false, scrollPosition: .none)
        } else {
            uiView.deselectRow(at: IndexPath(row: 0, section: 0), animated: false)
        }
    }
}

